function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Einstein stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Curiosity spark
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 30 + 20 * Math.sin(t), H/2 - 30 + 20 * Math.cos(t), 5, 0, 2 * Math.PI);
  ctx.fill();

  // Imagination bubble
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 30 + 30 * Math.sin(1.5 * t), H/2 - 50 + 30 * Math.cos(1.5 * t), 20, 0, 2 * Math.PI);
  ctx.stroke();

  // Book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 40, H/2 + 80, 80, 20);
  ctx.fillStyle = 'white';
  ctx.font = '12px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Theory of Relativity', W/2, H/2 + 90);

  ctx.restore();
}
